# Coordinator one-pass pooling for a mixture of native and fallback packets.
source('python_fallback/environment.R');clif_fallback_check_environment()
source('scripts/deployment_lib.R');source('python_fallback/verify_return.R')
a<-commandArgs(trailingOnly=TRUE)
if(length(a)<4L)stop('Usage: collect.R PARENT_BUNDLE OUTPUT PYTHON SITE_RETURN [...]')
bundle<-normalizePath(a[1],mustWork=TRUE);root<-path.expand(a[2]);python<-path.expand(a[3]);returns<-normalizePath(a[-c(1,2,3)],mustWork=TRUE)
python<-file.path(normalizePath(dirname(python),mustWork=TRUE),basename(python))
if(!file.exists(python))stop('Supply the pinned Python environment executable.')
bm<-deploy_validate_inventory(bundle,'bundle_manifest.json');bhash<-unname(tools::md5sum(file.path(bundle,'bundle_manifest.json')))
ms<-lapply(returns,deploy_validate_inventory);sites<-vapply(ms,`[[`,character(1),'site')
stopifnot(!anyDuplicated(sites),setequal(sites,unlist(bm$sites)))
for(i in seq_along(ms)){verify_stage2_return(ms[[i]],bm,bhash);deploy_check_csvs(returns[i])}
dir.create(root,recursive=TRUE,showWarnings=FALSE);root<-normalizePath(root)
state<-list(bundle_md5=bhash,return_manifest_md5=setNames(as.list(vapply(returns,function(p)unname(tools::md5sum(file.path(p,'return_manifest.json'))),character(1))),returns),python=python)
statefile<-file.path(root,'local/collection_inputs.json')
if(file.exists(statefile)){if(!identical(deploy_read(statefile),state))stop('Collection inputs changed; choose a fresh output directory.')}else deploy_json(state,statefile)
step<-function(key,script,args=character())deploy_step(root,key,script,args)
step('collect_one_pass','python_fallback/central_collect.R',c(bundle,file.path(root,'reports'),returns))
step('survival_reconstruct','diagnostics/stage2/central_survival.R',c(file.path(root,'survival_reconstruction'),file.path(returns,'survival')))
step('pooled_AJ_KM','diagnostics/pooled_survival/central_pool.R',c(file.path(root,'reports/pooled_survival'),file.path(root,'survival_reconstruction/grid'),file.path(root,'survival_reconstruction/sites',sites)))
deploy_step(root,'pool_prediction','diagnostics/stage2/central_prediction.py',c(file.path(root,'reports/pooled_prediction'),file.path(returns,'prediction')),python)
deploy_step(root,'plot_competing','diagnostics/pooled_survival/plot_competing.py',file.path(root,'reports/pooled_survival'),python)
cat('Native/PyArrow Stage2 collection complete. Reports: ',file.path(root,'reports'),'\n',sep='')
